<script setup>
import { computed,onMounted,ref } from 'vue'
import { supabase } from './supabase'
const TOTAL=77, START=22, CONTRACT='35-6404576'
const session=ref(null), email=ref(''), password=ref(''), authError=ref(''), busy=ref(false), tab=ref('home'), payments=ref([]), documents=ref([]), showPay=ref(false), showDoc=ref(false), notice=ref('')
const scheduleAmount=n=>n<=12?2475:n<=24?3465:n<=36?4455:n<=76?4950:1894
const dueDate=n=>new Date(2025,3+n-1,8).toLocaleDateString('th-TH',{day:'numeric',month:'short',year:'numeric'})
const installments=computed(()=>Array.from({length:TOTAL},(_,i)=>{const no=i+1,p=payments.value.find(x=>x.installment_no===no);return{no,amount:scheduleAmount(no),due:dueDate(no),paid:no<START||!!p,p}}))
const paidCount=computed(()=>installments.value.filter(x=>x.paid).length), remainingCount=computed(()=>TOTAL-paidCount.value), next=computed(()=>installments.value.find(x=>!x.paid)), remainingAmount=computed(()=>installments.value.filter(x=>!x.paid).reduce((s,x)=>s+x.amount,0)), progress=computed(()=>Math.round(paidCount.value/TOTAL*100))
const pay=ref({installment_no:22,paid_date:new Date().toISOString().slice(0,10),amount:3465,payer:'ผู้ผ่อนคนที่ 1',note:'',file:null})
const doc=ref({name:'',type:'พ.ร.บ.',expiry_date:'',file:null})
const money=n=>Number(n||0).toLocaleString('th-TH',{minimumFractionDigits:2,maximumFractionDigits:2})
async function login(){busy.value=true;authError.value='';const {error}=await supabase.auth.signInWithPassword({email:email.value,password:password.value});authError.value=error?.message||'';busy.value=false}
async function logout(){await supabase.auth.signOut()}
async function load(){if(!session.value)return;const [{data:p},{data:d}]=await Promise.all([supabase.from('payments').select('*').order('installment_no'),supabase.from('car_documents').select('*').order('created_at',{ascending:false})]);payments.value=p||[];documents.value=d||[]}
function choose(){pay.value.amount=scheduleAmount(Number(pay.value.installment_no))}
async function submitPayment(){if(!pay.value.file)return notice.value='กรุณาแนบสลิป';busy.value=true;const uid=session.value.user.id, ext=pay.value.file.name.split('.').pop(), path=`${uid}/${crypto.randomUUID()}.${ext}`;let r=await supabase.storage.from('payment-slips').upload(path,pay.value.file);if(r.error){notice.value=r.error.message;busy.value=false;return}r=await supabase.from('payments').insert({user_id:uid,contract_no:CONTRACT,installment_no:Number(pay.value.installment_no),paid_date:pay.value.paid_date,amount:Number(pay.value.amount),payer:pay.value.payer,note:pay.value.note,slip_path:path});if(r.error)notice.value=r.error.message;else{notice.value='บันทึกการชำระแล้ว';showPay.value=false;await load();if(next.value){pay.value.installment_no=next.value.no;choose()}}busy.value=false}
async function openSlip(p){const {data,error}=await supabase.storage.from('payment-slips').createSignedUrl(p.slip_path,300);if(error)notice.value=error.message;else window.open(data.signedUrl,'_blank')}
async function submitDoc(){if(!doc.value.file)return;busy.value=true;const uid=session.value.user.id,ext=doc.value.file.name.split('.').pop(),path=`${uid}/${crypto.randomUUID()}.${ext}`;let r=await supabase.storage.from('car-documents').upload(path,doc.value.file);if(!r.error)r=await supabase.from('car_documents').insert({user_id:uid,contract_no:CONTRACT,name:doc.value.name,type:doc.value.type,expiry_date:doc.value.expiry_date||null,file_path:path});notice.value=r.error?.message||'เพิ่มเอกสารแล้ว';showDoc.value=false;await load();busy.value=false}
async function openDoc(d){const {data,error}=await supabase.storage.from('car-documents').createSignedUrl(d.file_path,300);if(error)notice.value=error.message;else window.open(data.signedUrl,'_blank')}
onMounted(async()=>{const {data}=await supabase.auth.getSession();session.value=data.session;await load();supabase.auth.onAuthStateChange(async(_,s)=>{session.value=s;if(s)await load();else{payments.value=[];documents.value=[]}})})
</script>
<template>
<div v-if="!session" class="login-shell"><form class="login-card" @submit.prevent="login"><div class="login-logo">🚘</div><h1>ค่างวดรถของฉัน</h1><p>เข้าสู่ระบบด้วยบัญชี Supabase</p><label>อีเมล<input v-model.trim="email" type="email" autocomplete="email" required></label><label>รหัสผ่าน<input v-model="password" type="password" autocomplete="current-password" required></label><div v-if="authError" class="login-error">{{authError}}</div><button class="login-btn" :disabled="busy">{{busy?'กำลังเข้าสู่ระบบ…':'เข้าสู่ระบบ'}}</button></form></div>
<div v-else class="app-shell"><header class="top"><div><small>CAR PAYMENT</small><h1>ค่างวดรถของฉัน</h1></div><button class="logout-btn" @click="logout">ออกจากระบบ</button></header><main>
<section v-if="tab==='home'"><article class="card hero"><div class="hero-head"><div class="car-icon">🚘</div><div class="right"><b>MITSUBISHI Attrage</b><span>สัญญา {{CONTRACT}}</span></div></div><div class="stats"><div><span>ชำระแล้ว</span><strong>{{paidCount}} / 77 งวด</strong></div><div class="right"><span>งวดคงเหลือ</span><strong>{{remainingCount}} งวด</strong></div></div><div class="progress"><i :style="{width:progress+'%'}"></i></div><p class="balance">ยอดค่างวดคงเหลือ <b>{{money(remainingAmount)}} บาท</b></p><div class="quick-grid"><button @click="showPay=true">💳<span>ชำระค่างวด</span></button><button @click="tab='schedule'">📅<span>ตารางผ่อน</span></button><button @click="tab='history'">🧾<span>ประวัติชำระ</span></button><button @click="tab='docs'">📂<span>เอกสารรถ</span></button></div></article><article v-if="next" class="due-card"><div><small>งวดที่ {{next.no}} ต้องชำระ</small><h2>{{money(next.amount)}} บาท</h2><p>ครบกำหนด {{next.due}}</p></div><button class="orange" @click="showPay=true">แนบสลิป</button></article><article class="card detail"><h3>สถานะการผ่อน</h3><div><span>งวดที่ 1–21</span><b class="ok">✓ ชำระแล้ว</b></div><div><span>เริ่มบันทึกใหม่</span><b>งวดที่ 22</b></div></article></section>
<section v-else-if="tab==='schedule'" class="card page"><h2>ตารางผ่อน 77 งวด</h2><div class="list"><div v-for="x in installments" :key="x.no" class="row"><div><b>งวดที่ {{x.no}}</b><small>{{x.due}}</small></div><strong>{{money(x.amount)}}</strong><span :class="x.paid?'paid':'waiting'">{{x.paid?'ชำระแล้ว':'รอชำระ'}}</span></div></div></section>
<section v-else-if="tab==='history'" class="card page"><h2>ประวัติการชำระ</h2><div class="list"><div v-for="p in payments" :key="p.id" class="row"><div><b>งวดที่ {{p.installment_no}}</b><small>{{p.paid_date}} · {{p.payer}}</small></div><strong>{{money(p.amount)}}</strong><button class="primary" @click="openSlip(p)">ดูสลิป</button></div><p v-if="!payments.length" class="empty">ยังไม่มีรายการใหม่หลังงวด 21</p></div></section>
<section v-else class="card page"><div class="title-line"><div><h2>เอกสารรถ</h2><p class="muted">เอกสารส่วนตัวจะเปิดด้วย signed URL ชั่วคราว</p></div><button class="primary" @click="showDoc=true">+ เพิ่ม</button></div><div class="list"><div v-for="d in documents" :key="d.id" class="row"><div><b>{{d.name}}</b><small>{{d.type}}</small></div><button class="primary" @click="openDoc(d)">เปิดดู</button></div><p v-if="!documents.length" class="empty">ยังไม่มีเอกสาร</p></div></section>
</main><nav class="bottom"><button :class="{active:tab==='home'}" @click="tab='home'">⌂<span>ภาพรวม</span></button><button :class="{active:tab==='schedule'}" @click="tab='schedule'">▦<span>ค่างวด</span></button><button :class="{active:tab==='history'}" @click="tab='history'">◷<span>ประวัติ</span></button><button :class="{active:tab==='docs'}" @click="tab='docs'">▤<span>เอกสาร</span></button></nav>
<div v-if="notice" class="toast" @click="notice=''">{{notice}}</div>
<div v-if="showPay" class="modal" @click.self="showPay=false"><form class="modal-card" @submit.prevent="submitPayment"><button type="button" class="close" @click="showPay=false">×</button><h2>บันทึกชำระ / แนบสลิป</h2><label>งวด<select v-model="pay.installment_no" @change="choose"><option v-for="n in 56" :value="n+21">งวดที่ {{n+21}}</option></select></label><div class="two"><label>วันที่<input v-model="pay.paid_date" type="date" required></label><label>จำนวน<input v-model.number="pay.amount" type="number" step="0.01" required></label></div><label>ผู้ชำระ<select v-model="pay.payer"><option>ผู้ผ่อนคนที่ 1</option><option>ผู้ผ่อนคนที่ 2</option></select></label><label>สลิป<input type="file" accept="image/*,.pdf" @change="e=>pay.file=e.target.files[0]" required></label><label>หมายเหตุ<input v-model="pay.note"></label><button class="primary full" :disabled="busy">บันทึก</button></form></div>
<div v-if="showDoc" class="modal" @click.self="showDoc=false"><form class="modal-card" @submit.prevent="submitDoc"><button type="button" class="close" @click="showDoc=false">×</button><h2>เพิ่มเอกสารรถ</h2><label>ชื่อ<input v-model="doc.name" required></label><label>ประเภท<select v-model="doc.type"><option>สัญญาเช่าซื้อ</option><option>ตารางภาระหนี้</option><option>เล่มทะเบียน</option><option>กรมธรรม์ประกันภัย</option><option>พ.ร.บ.</option><option>ภาษีรถยนต์</option><option>ซ่อมบำรุง</option><option>อื่น ๆ</option></select></label><label>วันหมดอายุ<input v-model="doc.expiry_date" type="date"></label><label>ไฟล์<input type="file" @change="e=>doc.file=e.target.files[0]" required></label><button class="primary full" :disabled="busy">บันทึกเอกสาร</button></form></div></div>
</template>